(7619742, 1233964, 28742, '<td valign="top">Glanced at the thumbnails, saw this, opened it and thought - there''s the winner right there. I might come back and delete this whole comment when I start voting in case I am way off base, but as of now, I''m calling this Game Over. Here''s a 10 just to help make it so.</td>', 'Glanced at the thumbnails, saw this, opened it and thought - there''s the winner right there. I might come back and delete this whole comment when I start voting in case I am way off base, but as of now, I''m calling this Game Over. Here''s a 10 just to help make it so.', '2019-03-15 00:12:33.000000', NULL, 1),
(7619746, 1234227, 28742, '<td valign="top">Crap. I had my pick for the blue already and now this. I''ll call it Red for this one, but it will probably be blue. Deserves either or both, though. :)</td>', 'Crap. I had my pick for the blue already and now this. I''ll call it Red for this one, but it will probably be blue. Deserves either or both, though. :)', '2019-03-15 00:18:44.000000', NULL, 1),
