(7619881, 1234227, 98565, '<td valign="top">Perfect! Light, pose, clothing, postprocessing - awesome. Even the hairstyle does fit into the period</td>', 'Perfect! Light, pose, clothing, postprocessing - awesome. Even the hairstyle does fit into the period', '2019-03-15 15:43:05.000000', NULL, 1),
